import { internalMutationGeneric, queryGeneric } from "convex/server";
import { ConvexError, v } from "convex/values";

const KEEP_MS = 24 * 60 * 60 * 1000;
const PAGE = 100;

/**
 * The deployment URL is public, so reads need READ_TOKEN (generated by the app on
 * deploy and stored only there + in this deployment's environment variables).
 */
function checkToken(token: string) {
  const expected = process.env.READ_TOKEN;
  if (!expected || token !== expected) throw new ConvexError("unauthorized");
}

/** Newest stored event time — where a fresh subscription starts from. */
export const cursor = queryGeneric({
  args: { token: v.string() },
  handler: async (ctx, { token }) => {
    checkToken(token);
    const last = await ctx.db.query("events").order("desc").first();
    return last?._creationTime ?? 0;
  },
});

/** Events stored after `after` (a `_creationTime`), oldest first. */
export const since = queryGeneric({
  args: { token: v.string(), after: v.number() },
  handler: async (ctx, { token, after }) => {
    checkToken(token);
    const rows = await ctx.db
      .query("events")
      .withIndex("by_creation_time", (q) => q.gt("_creationTime", after))
      .take(PAGE);
    return rows.map((r) => ({ id: r._id, at: r._creationTime, event: r.event, body: r.body }));
  },
});

export const record = internalMutationGeneric({
  args: { delivery: v.optional(v.string()), event: v.string(), body: v.any() },
  handler: async (ctx, args) => {
    // At-least-once delivery: drop repeats of the same delivery.
    if (args.delivery) {
      const seen = await ctx.db
        .query("events")
        .withIndex("by_delivery", (q) => q.eq("delivery", args.delivery))
        .first();
      if (seen) return;
    }
    await ctx.db.insert("events", args);
  },
});

export const prune = internalMutationGeneric({
  args: {},
  handler: async (ctx) => {
    const old = await ctx.db
      .query("events")
      .withIndex("by_creation_time", (q) => q.lt("_creationTime", Date.now() - KEEP_MS))
      .take(500);
    await Promise.all(old.map((r) => ctx.db.delete(r._id)));
  },
});
